-- fxmanifest.lua — the island's road names in game. Drop this folder into
-- resources/ as "island-streets" and add `ensure island-streets` to server.cfg.
-- Client-only, no dependencies. data.lua is generated by tools/gen-island-streets.py.
fx_version 'cerulean'
game 'gta5'

description 'Island street names: HUD street name, 3D junction signs, pause-map blips'

client_scripts {
    'data.lua',    -- sets ISLAND_STREETS (must load first)
    'client.lua',
}
